class Solution {
public:
    bool isCovered(vector<vector<int>>& ranges, int left, int right) {
        for (int x = left; x <= right; ++x) {
            bool ok = false;
            for (auto& r : ranges)
                if (r[0] <= x && x <= r[1]) { ok = true; break; }
            if (!ok) return false;
        }
        return true;
    }
};

