        for (auto& r : ranges) { ++diff[r[0]]; --diff[r[1] + 1]; }
        int cur = 0;
        for (int x = 1; x <= 50; ++x) {
            cur += diff[x];
            if (left <= x && x <= right && cur == 0) return false;
        }
        return true;
    }
};

